"""Supplier reliability and purchase orders (C15, C16, C17)."""
from events import DepotError, emit

START_RELIABILITY = 3
MIN_RELIABILITY = 0
MAX_RELIABILITY = 5
SUSPEND_AT = 1      # reliability <= 1 means suspended
REINSTATE_TO = 2


def reliability(s, supplier):
    if not isinstance(supplier, str) or supplier not in s["suppliers"]:
        raise DepotError("UNKNOWN_SUPPLIER")
    return s["suppliers"][supplier]


def place_order(s, supplier, sku, qty, due_day, wh):
    """Create an open order and return its id. A supplier appears on its first order."""
    if not isinstance(supplier, str) or not supplier:
        raise DepotError("BAD_ARG")
    rel = s["suppliers"].get(supplier)
    if rel is not None and rel <= SUSPEND_AT:
        raise DepotError("SUPPLIER_SUSPENDED")
    if rel is None:
        s["suppliers"][supplier] = START_RELIABILITY
    oid = s["next_order_id"]
    s["next_order_id"] = oid + 1
    s["orders"][str(oid)] = {
        "supplier": supplier, "sku": sku, "qty": qty,
        "due_day": due_day, "wh": wh, "open": True,
    }
    return oid


def open_order(s, order_id):
    order = s["orders"].get(str(order_id))
    if order is None:
        raise DepotError("UNKNOWN_ORDER")
    if not order["open"]:
        raise DepotError("ORDER_CLOSED")
    return order


def record_delivery(s, supplier, late):
    """C15: on time +1, late -1, clamped to [0, 5]. Emits SUPPLIER_SUSPENDED on becoming suspended."""
    old = s["suppliers"][supplier]
    new = old - 1 if late else old + 1
    new = min(MAX_RELIABILITY, max(MIN_RELIABILITY, new))
    s["suppliers"][supplier] = new
    if old > SUSPEND_AT >= new:
        emit(s["notes"], "SUPPLIER_SUSPENDED", supplier)


def reinstate(s, supplier):
    if not isinstance(supplier, str) or supplier not in s["suppliers"]:
        raise DepotError("UNKNOWN_SUPPLIER")
    s["suppliers"][supplier] = REINSTATE_TO
