"""Depot: multi-warehouse inventory and cash ledger.

Each mutating call works on a deep copy of the state. If it raises DepotError the copy is
discarded, so a failed operation changes nothing. On success the previous state is kept so
that undo() can restore it once.
"""
import copy
import json

import money
import suppliers
from events import DepotError, emit

SAVE_VERSION = 1
_REQUIRED_CONFIG = (
    "markup", "bulk_threshold", "bulk_discount_pct",
    "storage_cents_per_unit_day", "transfer_credit_cents_per_unit",
)
_STATE_KEYS = frozenset({
    "day", "cash", "items", "lots", "shipped", "returned", "ship_log", "held_log",
    "fired", "suppliers", "orders", "next_order_id", "notes",
})


def _is_int(v):
    return type(v) is int          # excludes bool


def _check_qty(qty):
    if not _is_int(qty) or qty <= 0:
        raise DepotError("BAD_ARG")


def _check_nonneg(v):
    if not _is_int(v) or v < 0:
        raise DepotError("BAD_ARG")


def _take_fifo(lots, qty):
    """Remove qty units from the front (oldest) of a lot list. Returns the taken [day, qty] pieces."""
    taken = []
    while qty > 0:
        day, q = lots[0]
        t = min(q, qty)
        taken.append([day, t])
        if t == q:
            lots.pop(0)
        else:
            lots[0][1] = q - t
        qty -= t
    return taken


def _validate_state(st, warehouses):
    def need(cond):
        if not cond:
            raise DepotError("BAD_SAVE")

    need(isinstance(st, dict) and set(st) == _STATE_KEYS)
    need(_is_int(st["day"]) and st["day"] >= 0)
    need(_is_int(st["cash"]))

    items = st["items"]
    need(isinstance(items, dict))
    for sku, it in items.items():
        need(isinstance(sku, str))
        need(isinstance(it, dict) and set(it) == {"unit_cost", "reorder_level", "shelf_life_days"})
        need(_is_int(it["unit_cost"]) and it["unit_cost"] > 0)
        need(_is_int(it["reorder_level"]) and it["reorder_level"] >= 0)
        sl = it["shelf_life_days"]
        need(sl is None or (_is_int(sl) and sl >= 1))

    lots = st["lots"]
    need(isinstance(lots, dict) and set(lots) == set(items))
    for sku in items:
        byw = lots[sku]
        need(isinstance(byw, dict) and set(byw) == set(warehouses))
        for lst in byw.values():
            need(isinstance(lst, list))
            for p in lst:
                need(isinstance(p, list) and len(p) == 2
                     and _is_int(p[0]) and _is_int(p[1]) and p[1] > 0)

    for key in ("shipped", "returned"):
        d = st[key]
        need(isinstance(d, dict))
        for k, v in d.items():
            need(k in items and _is_int(v) and v >= 0)

    need(isinstance(st["ship_log"], list))
    for e in st["ship_log"]:
        need(isinstance(e, list) and len(e) == 2 and all(_is_int(x) for x in e))

    hl = st["held_log"]
    need(isinstance(hl, list) and len(hl) == st["day"] + 1
         and all(_is_int(x) and x >= 0 for x in hl))

    need(isinstance(st["fired"], list))
    for e in st["fired"]:
        need(isinstance(e, list) and len(e) == 2 and e[0] in items and e[1] in warehouses)

    sup = st["suppliers"]
    need(isinstance(sup, dict))
    for k, v in sup.items():
        need(isinstance(k, str) and _is_int(v) and 0 <= v <= 5)

    orders = st["orders"]
    need(isinstance(orders, dict))
    for k, o in orders.items():
        need(isinstance(k, str) and isinstance(o, dict)
             and set(o) == {"supplier", "sku", "qty", "due_day", "wh", "open"})
        need(isinstance(o["supplier"], str) and o["supplier"] in sup)
        need(isinstance(o["sku"], str) and o["sku"] in items)
        need(_is_int(o["qty"]) and o["qty"] > 0 and _is_int(o["due_day"]))
        need(o["wh"] is None or o["wh"] in warehouses)
        need(isinstance(o["open"], bool))

    need(_is_int(st["next_order_id"]) and st["next_order_id"] >= 1)
    need(isinstance(st["notes"], list))
    for n in st["notes"]:
        need(isinstance(n, list) and len(n) >= 1 and isinstance(n[0], str))


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, config=None):
        names = list(warehouses)
        if not names or not all(isinstance(n, str) for n in names) or len(set(names)) != len(names):
            raise DepotError("BAD_ARG")
        if not isinstance(capacities, dict):
            raise DepotError("BAD_ARG")
        for n in names:
            if n not in capacities:
                raise DepotError("BAD_ARG")
            _check_nonneg(capacities[n])
        if not _is_int(opening_cash):
            raise DepotError("BAD_ARG")
        money.check_mode(rounding_mode)

        cfg = money.load_data()
        if config:
            cfg.update(config)
        for key in _REQUIRED_CONFIG:
            if key not in cfg:
                raise DepotError("BAD_ARG")

        self._wh = names
        self._cap = {n: capacities[n] for n in names}
        self._mode = rounding_mode
        self._cfg = cfg
        self._st = {
            "day": 0, "cash": opening_cash, "items": {}, "lots": {},
            "shipped": {}, "returned": {}, "ship_log": [], "held_log": [0],
            "fired": [], "suppliers": {}, "orders": {}, "next_order_id": 1, "notes": [],
        }
        self._snap = None

    # ----- helpers -------------------------------------------------------

    def _run(self, fn, *args, undoable=True):
        """Run a mutating operation on a copy; commit only if it does not raise."""
        old = self._st
        work = copy.deepcopy(old)
        result = fn(work, *args)
        self._st = work
        self._snap = old if undoable else None
        return result

    def _check_sku(self, s, sku):
        if not isinstance(sku, str) or sku not in s["items"]:
            raise DepotError("UNKNOWN_SKU")

    def _check_wh(self, wh):
        if not isinstance(wh, str) or wh not in self._wh:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _stock_at(s, sku, wh):
        return sum(q for _, q in s["lots"][sku][wh])

    def _wh_units(self, s, wh):
        return sum(self._stock_at(s, sku, wh) for sku in s["items"])

    def _total_units(self, s):
        return sum(self._wh_units(s, w) for w in self._wh)

    def _rearm(self, s, sku, wh):
        """C14: stock above reorder level re-arms the REORDER notification."""
        if [sku, wh] in s["fired"] and self._stock_at(s, sku, wh) > s["items"][sku]["reorder_level"]:
            s["fired"].remove([sku, wh])

    # ----- operations (mutating) ----------------------------------------

    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        return self._run(self._do_add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _do_add_item(self, s, sku, unit_cost, reorder_level, shelf_life_days):
        if not isinstance(sku, str) or not sku:
            raise DepotError("BAD_ARG")
        if sku in s["items"]:
            raise DepotError("DUPLICATE_SKU")
        if not _is_int(unit_cost) or unit_cost <= 0:
            raise DepotError("BAD_ARG")
        _check_nonneg(reorder_level)
        if shelf_life_days is not None:
            _check_nonneg(shelf_life_days)
        s["items"][sku] = {
            "unit_cost": unit_cost,
            "reorder_level": reorder_level,
            "shelf_life_days": shelf_life_days or None,   # 0 means non-perishable
        }
        s["lots"][sku] = {w: [] for w in self._wh}

    def receive(self, sku, qty, wh):
        return self._run(self._do_receive, sku, qty, wh)

    def _do_receive(self, s, sku, qty, wh):
        self._check_sku(s, sku)
        self._check_wh(wh)
        _check_qty(qty)
        if s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_units(s, wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        cost = s["items"][sku]["unit_cost"] * qty
        if s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        s["cash"] -= cost
        s["lots"][sku][wh].append([s["day"], qty])
        self._rearm(s, sku, wh)

    def receive_bulk(self, receipts):
        return self._run(self._do_receive_bulk, receipts)

    def _do_receive_bulk(self, s, receipts):
        try:
            rows = [(sku, qty, wh) for sku, qty, wh in receipts]
        except (TypeError, ValueError):
            raise DepotError("BAD_ARG")
        for sku, qty, wh in rows:
            self._do_receive(s, sku, qty, wh)     # any failure rolls back the whole batch

    def ship(self, sku, qty, wh, price):
        return self._run(self._do_ship, sku, qty, wh, price)

    def _do_ship(self, s, sku, qty, wh, price):
        self._check_sku(s, sku)
        self._check_wh(wh)
        _check_qty(qty)
        _check_nonneg(price)
        if self._stock_at(s, sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        _take_fifo(s["lots"][sku][wh], qty)
        s["cash"] += money.sale_revenue(
            price, qty, self._cfg["bulk_threshold"], self._cfg["bulk_discount_pct"], self._mode)
        s["shipped"][sku] = s["shipped"].get(sku, 0) + qty
        s["ship_log"].append([s["day"], qty])
        level = s["items"][sku]["reorder_level"]
        if self._stock_at(s, sku, wh) <= level and [sku, wh] not in s["fired"]:
            s["fired"].append([sku, wh])
            emit(s["notes"], "REORDER", sku, wh)

    def transfer(self, sku, qty, from_wh, to_wh):
        return self._run(self._do_transfer, sku, qty, from_wh, to_wh)

    def _do_transfer(self, s, sku, qty, from_wh, to_wh):
        self._check_sku(s, sku)
        self._check_wh(from_wh)
        self._check_wh(to_wh)
        _check_qty(qty)
        if from_wh == to_wh:
            raise DepotError("BAD_ARG")
        if self._stock_at(s, sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._wh_units(s, to_wh) + qty > self._cap[to_wh]:
            raise DepotError("CAPACITY")
        cost = money.transfer_cost(qty, self._cfg["transfer_credit_cents_per_unit"])
        if s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        s["cash"] -= cost
        pieces = _take_fifo(s["lots"][sku][from_wh], qty)
        dst = s["lots"][sku][to_wh]
        dst.extend(pieces)
        dst.sort(key=lambda p: p[0])            # moved lots keep their original day stamps
        self._rearm(s, sku, from_wh)
        self._rearm(s, sku, to_wh)

    def return_goods(self, sku, qty, wh, price):
        return self._run(self._do_return, sku, qty, wh, price)

    def _do_return(self, s, sku, qty, wh, price):
        self._check_sku(s, sku)
        self._check_wh(wh)
        _check_qty(qty)
        _check_nonneg(price)
        if s["returned"].get(sku, 0) + qty > s["shipped"].get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        if self._wh_units(s, wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        refund = price * qty
        if s["cash"] - refund < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        s["cash"] -= refund
        s["lots"][sku][wh].append([s["day"], qty])
        s["returned"][sku] = s["returned"].get(sku, 0) + qty
        self._rearm(s, sku, wh)

    def audit(self, counts):
        return self._run(self._do_audit, counts)

    def _do_audit(self, s, counts):
        if not isinstance(counts, dict):
            raise DepotError("BAD_ARG")
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for key, counted in counts.items():
            try:
                sku, wh = key
            except (TypeError, ValueError):
                raise DepotError("BAD_ARG")
            self._check_sku(s, sku)
            self._check_wh(wh)
            _check_nonneg(counted)
        for key in sorted(counts):
            sku, wh = key
            ledger = self._stock_at(s, sku, wh)
            counted = counts[key]
            if ledger != counted:
                emit(s["notes"], "AUDIT_MISMATCH", sku, wh, ledger, counted)

    def advance_day(self):
        self._run(self._do_advance, undoable=False)

    def _do_advance(self, s):
        # C21 order: storage charge, then expiry, then the overdrawn check.
        units = self._total_units(s)
        s["cash"] -= money.storage_charge(units, self._cfg["storage_cents_per_unit_day"])
        for sku in sorted(s["items"]):
            life = s["items"][sku]["shelf_life_days"]
            if life is None:
                continue
            for wh in sorted(self._wh):
                lots = s["lots"][sku][wh]
                stale = [p for p in lots if s["day"] - p[0] > life]
                if stale:
                    lots[:] = [p for p in lots if s["day"] - p[0] <= life]
                    emit(s["notes"], "EXPIRY", sku, wh, sum(p[1] for p in stale))
        if s["cash"] < 0:
            emit(s["notes"], "OVERDRAWN")
        s["day"] += 1
        s["held_log"].append(self._total_units(s))

    def add_supplier_unused(self):  # placeholder removed below
        raise NotImplementedError

    def place_order(self, supplier, sku, qty, due_day, wh=None):
        return self._run(self._do_place_order, supplier, sku, qty, due_day, wh)

    def _do_place_order(self, s, supplier, sku, qty, due_day, wh):
        self._check_sku(s, sku)
        _check_qty(qty)
        if not _is_int(due_day):
            raise DepotError("BAD_ARG")
        if wh is not None:
            self._check_wh(wh)
        return suppliers.place_order(s, supplier, sku, qty, due_day, wh)

    def deliver(self, order_id, day):
        return self._run(self._do_deliver, order_id, day)

    def _do_deliver(self, s, order_id, day):
        order = suppliers.open_order(s, order_id)
        if not _is_int(day) or day != s["day"]:
            raise DepotError("BAD_ARG")
        wh = order["wh"]
        if wh is None:
            raise DepotError("UNKNOWN_WAREHOUSE")   # order placed without a destination warehouse
        sku, qty = order["sku"], order["qty"]
        unit_cost = s["items"][sku]["unit_cost"]
        late = day > order["due_day"]
        if late:
            amount = money.late_payment(unit_cost, qty, self._cfg.get("late_penalty_pct"), self._mode)
        else:
            amount = unit_cost * qty
        if s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_units(s, wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        if s["cash"] - amount < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        s["cash"] -= amount
        s["lots"][sku][wh].append([s["day"], qty])
        order["open"] = False
        suppliers.record_delivery(s, order["supplier"], late)
        self._rearm(s, sku, wh)

    def reinstate(self, supplier):
        return self._run(suppliers.reinstate, supplier)

    def undo(self):
        if self._snap is None:
            raise DepotError("UNDO_BLOCKED")
        self._st = self._snap
        self._snap = None

    def load(self, text):
        self._run(self._do_load, text)

    def _do_load(self, s, text):
        try:
            obj = json.loads(text)
        except (TypeError, ValueError):
            raise DepotError("BAD_SAVE")
        if not isinstance(obj, dict) or type(obj.get("version")) is not int \
                or obj["version"] != SAVE_VERSION:
            raise DepotError("BAD_SAVE")
        st = obj.get("state")
        try:
            _validate_state(st, self._wh)
        except DepotError:
            raise
        except Exception:
            raise DepotError("BAD_SAVE")
        st["notes"] = [tuple(n) for n in st["notes"]]
        s.clear()
        s.update(st)

    # ----- read-only -----------------------------------------------------

    @property
    def cash(self):
        return self._st["cash"]

    @property
    def day(self):
        return self._st["day"]

    def reliability(self, supplier):
        return suppliers.reliability(self._st, supplier)

    def notifications(self):
        return list(self._st["notes"])

    def list_price(self, sku):
        self._check_sku(self._st, sku)
        return money.list_price(self._st["items"][sku]["unit_cost"], self._cfg["markup"], self._mode)

    def stock(self, sku, wh=None):
        self._check_sku(self._st, sku)
        if wh is None:
            return sum(self._stock_at(self._st, sku, w) for w in self._wh)
        self._check_wh(wh)
        return self._stock_at(self._st, sku, wh)

    def report(self):
        s = self._st
        rows = []
        for sku in sorted(s["items"]):
            unit_cost = s["items"][sku]["unit_cost"]
            for wh in sorted(self._wh):
                units = self._stock_at(s, sku, wh)
                if units > 0:
                    rows.append((sku, wh, units, units * unit_cost))
        return rows

    def turnover(self, start_day, end_day):
        s = self._st
        if not _is_int(start_day) or not _is_int(end_day) \
                or start_day < 0 or end_day > s["day"] or start_day > end_day:
            raise DepotError("BAD_ARG")
        return money.turnover(s["ship_log"], s["held_log"], start_day, end_day)

    def save(self):
        return json.dumps({"version": SAVE_VERSION, "state": self._st}, sort_keys=True)
