"""Independent reference model of the Depot spec, for differential testing.

Written from the specification rather than from inventory.py, with a different structure. Each
mutating call runs inside a transaction that restores a deep copy of the state if anything
raises. Configuration is hard-coded from the spec's data table and nothing is read from disk.

Where the spec leaves a choice open, this model makes the same choice as inventory.py, so a
difference found by diff testing points at a real divergence. Those choices are listed in the
module's notes and in the accompanying response.

Exports: Depot, DepotError, simulate.
"""
import copy
import decimal
import json
import random
from decimal import Decimal
from fractions import Fraction


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


# Data table (data.toml), hard-coded on purpose.
MARKUP = Decimal("0.35")
BULK_THRESHOLD = 20
BULK_DISCOUNT_PCT = 10
STORAGE_PER_UNIT_DAY = 2
TRANSFER_PER_UNIT = 25
DEMAND = {"BOLT": (5, 40), "GLUE": (0, 6), "FILM": (1, 12)}

START_RELIABILITY = 3
SUSPEND_AT = 1
REINSTATE_TO = 2

ROUNDING_MODES = frozenset({
    decimal.ROUND_CEILING, decimal.ROUND_DOWN, decimal.ROUND_FLOOR,
    decimal.ROUND_HALF_DOWN, decimal.ROUND_HALF_EVEN, decimal.ROUND_HALF_UP,
    decimal.ROUND_UP, decimal.ROUND_05UP,
})

SAVE_VERSION = 1
SAVE_KEYS = frozenset({
    "day", "cash", "items", "lots", "shipped", "returned", "ship_log", "held",
    "fired", "suppliers", "orders", "next_order", "notes",
})


def _err(code):
    raise DepotError(code)


def _is_int(v):
    return type(v) is int          # excludes bool


def _to_cents(amount, mode):
    return int(Decimal(amount).quantize(Decimal(1), rounding=mode))


def _take_fifo(lst, qty):
    """Remove qty units from the front of a day-sorted lot list. Caller checks stock first."""
    taken, kept, need = [], [], qty
    for day, q in lst:
        if need == 0:
            kept.append([day, q])
        elif q <= need:
            taken.append([day, q])
            need -= q
        else:
            taken.append([day, need])
            kept.append([day, q - need])
            need = 0
    lst[:] = kept
    return taken


def _validate_save(st, wh_names):
    def need(cond):
        if not cond:
            _err("BAD_SAVE")

    need(isinstance(st, dict) and set(st) == SAVE_KEYS)
    need(_is_int(st["day"]) and st["day"] >= 0)
    need(_is_int(st["cash"]))
    need(_is_int(st["next_order"]) and st["next_order"] >= 1)

    items = st["items"]
    need(isinstance(items, dict))
    for sku, it in items.items():
        need(isinstance(sku, str) and isinstance(it, dict) and set(it) == {"unit", "reorder", "life"})
        need(_is_int(it["unit"]) and it["unit"] > 0)
        need(_is_int(it["reorder"]) and it["reorder"] >= 0)
        need(it["life"] is None or (_is_int(it["life"]) and it["life"] >= 1))

    lots = st["lots"]
    need(isinstance(lots, dict) and set(lots) == set(items))
    for sku in items:
        byw = lots[sku]
        need(isinstance(byw, dict) and set(byw) == set(wh_names))
        for lst in byw.values():
            need(isinstance(lst, list))
            for p in lst:
                need(isinstance(p, list) and len(p) == 2
                     and _is_int(p[0]) and _is_int(p[1]) and p[1] > 0)

    for key in ("shipped", "returned"):
        d = st[key]
        need(isinstance(d, dict) and all(k in items and _is_int(v) and v >= 0 for k, v in d.items()))

    need(isinstance(st["ship_log"], list))
    for e in st["ship_log"]:
        need(isinstance(e, list) and len(e) == 2 and all(_is_int(x) for x in e))

    held = st["held"]
    need(isinstance(held, list) and len(held) == st["day"] + 1
         and all(_is_int(x) and x >= 0 for x in held))

    need(isinstance(st["fired"], list))
    for e in st["fired"]:
        need(isinstance(e, list) and len(e) == 2 and e[0] in items and e[1] in wh_names)

    sup = st["suppliers"]
    need(isinstance(sup, dict))
    for k, v in sup.items():
        need(isinstance(k, str) and _is_int(v) and 0 <= v <= 5)

    orders = st["orders"]
    need(isinstance(orders, dict))
    for k, o in orders.items():
        need(isinstance(k, str) and isinstance(o, dict)
             and set(o) == {"supplier", "sku", "qty", "due", "wh", "open"})
        need(o["supplier"] in sup and o["sku"] in items)
        need(_is_int(o["qty"]) and o["qty"] > 0 and _is_int(o["due"]))
        need(o["wh"] is None or o["wh"] in wh_names)
        need(isinstance(o["open"], bool))

    need(isinstance(st["notes"], list))
    for n in st["notes"]:
        need(isinstance(n, list) and len(n) >= 1 and isinstance(n[0], str))

    st["notes"] = [tuple(n) for n in st["notes"]]
    st["fired"] = [list(e) for e in st["fired"]]
    return st


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, config=None):
        if not isinstance(warehouses, (list, tuple)) or not warehouses:
            _err("BAD_ARG")
        names = list(warehouses)
        if any(not isinstance(n, str) for n in names) or len(set(names)) != len(names):
            _err("BAD_ARG")
        if not isinstance(capacities, dict):
            _err("BAD_ARG")
        for n in names:
            if n not in capacities or not _is_int(capacities[n]) or capacities[n] < 0:
                _err("BAD_ARG")
        if not _is_int(opening_cash):
            _err("BAD_ARG")
        if not isinstance(rounding_mode, str) or rounding_mode not in ROUNDING_MODES:
            _err("BAD_ARG")

        late = None
        if config is not None:
            # Only late_penalty_pct is accepted as an override. inventory.py accepts any key.
            if not isinstance(config, dict) or set(config) - {"late_penalty_pct"}:
                _err("BAD_ARG")
            late = config.get("late_penalty_pct")
            if late is not None and (not _is_int(late) or not 0 <= late <= 100):
                _err("BAD_ARG")

        self._wh = names
        self._cap = {n: capacities[n] for n in names}
        self._mode = rounding_mode
        self._late = late
        self._prev = None
        self._s = {
            "day": 0, "cash": opening_cash, "items": {}, "lots": {},
            "shipped": {}, "returned": {}, "ship_log": [], "held": [0],
            "fired": [], "suppliers": {}, "orders": {}, "next_order": 1, "notes": [],
        }

    # ----- transactions and helpers -----------------------------------------

    def _txn(self, fn, *args, undoable=True):
        before = copy.deepcopy(self._s)
        try:
            out = fn(*args)
            self._rearm()
        except BaseException:
            self._s = before
            raise
        self._prev = before if undoable else None
        return out

    def _need_sku(self, sku):
        if not isinstance(sku, str) or sku not in self._s["items"]:
            _err("UNKNOWN_SKU")

    def _need_wh(self, wh):
        if not isinstance(wh, str) or wh not in self._cap:
            _err("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _need_qty(qty):
        if not _is_int(qty) or qty <= 0:
            _err("BAD_ARG")

    @staticmethod
    def _need_nonneg(v):
        if not _is_int(v) or v < 0:
            _err("BAD_ARG")

    def _stock(self, sku, wh):
        return sum(q for _, q in self._s["lots"][sku][wh])

    def _wh_units(self, wh):
        return sum(self._stock(sku, wh) for sku in self._s["items"])

    def _total_units(self):
        return sum(self._wh_units(w) for w in self._wh)

    def _rearm(self):
        """C14: a pair whose stock is above its reorder level becomes armed again."""
        s = self._s
        for sku, it in s["items"].items():
            for wh in self._wh:
                pair = [sku, wh]
                if pair in s["fired"] and self._stock(sku, wh) > it["reorder"]:
                    s["fired"].remove(pair)

    # ----- mutating operations ----------------------------------------------

    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        return self._txn(self._add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _add_item(self, sku, unit_cost, reorder_level, shelf_life_days):
        s = self._s
        if not isinstance(sku, str) or not sku:
            _err("BAD_ARG")
        if sku in s["items"]:
            _err("DUPLICATE_SKU")
        if not _is_int(unit_cost) or unit_cost <= 0:
            _err("BAD_ARG")
        self._need_nonneg(reorder_level)
        if shelf_life_days is not None:
            self._need_nonneg(shelf_life_days)
        s["items"][sku] = {
            "unit": unit_cost,
            "reorder": reorder_level,
            "life": shelf_life_days or None,      # 0 means non-perishable
        }
        s["lots"][sku] = {wh: [] for wh in self._wh}

    def receive(self, sku, qty, wh):
        return self._txn(self._receive, sku, qty, wh)

    def _receive(self, sku, qty, wh):
        s = self._s
        self._need_sku(sku)
        self._need_wh(wh)
        self._need_qty(qty)
        if s["cash"] < 0:
            _err("OVERDRAWN")
        if self._wh_units(wh) + qty > self._cap[wh]:
            _err("CAPACITY")
        cost = s["items"][sku]["unit"] * qty
        if s["cash"] - cost < 0:
            _err("INSUFFICIENT_FUNDS")
        s["cash"] -= cost
        s["lots"][sku][wh].append([s["day"], qty])

    def receive_bulk(self, receipts):
        # Atomicity comes from the transaction: any failing row rolls back the whole batch.
        return self._txn(self._receive_bulk, receipts)

    def _receive_bulk(self, receipts):
        try:
            rows = [(sku, qty, wh) for sku, qty, wh in receipts]
        except (TypeError, ValueError):
            _err("BAD_ARG")
        for sku, qty, wh in rows:
            self._receive(sku, qty, wh)

    def ship(self, sku, qty, wh, price):
        return self._txn(self._ship, sku, qty, wh, price)

    def _ship(self, sku, qty, wh, price):
        s = self._s
        self._need_sku(sku)
        self._need_wh(wh)
        self._need_qty(qty)
        self._need_nonneg(price)
        if self._stock(sku, wh) < qty:
            _err("INSUFFICIENT_STOCK")
        _take_fifo(s["lots"][sku][wh], qty)

        gross = Decimal(price * qty)
        if qty >= BULK_THRESHOLD:
            gross = gross * (100 - BULK_DISCOUNT_PCT) / 100
        s["cash"] += _to_cents(gross, self._mode)

        s["shipped"][sku] = s["shipped"].get(sku, 0) + qty
        s["ship_log"].append([s["day"], qty])

        if self._stock(sku, wh) <= s["items"][sku]["reorder"] and [sku, wh] not in s["fired"]:
            s["fired"].append([sku, wh])
            s["notes"].append(("REORDER", sku, wh))

    def transfer(self, sku, qty, from_wh, to_wh):
        return self._txn(self._transfer, sku, qty, from_wh, to_wh)

    def _transfer(self, sku, qty, from_wh, to_wh):
        s = self._s
        self._need_sku(sku)
        self._need_wh(from_wh)
        self._need_wh(to_wh)
        self._need_qty(qty)
        if from_wh == to_wh:
            _err("BAD_ARG")
        if self._stock(sku, from_wh) < qty:
            _err("INSUFFICIENT_STOCK")
        if self._wh_units(to_wh) + qty > self._cap[to_wh]:
            _err("CAPACITY")
        cost = TRANSFER_PER_UNIT * qty          # C11: charged to the sending side (assumption)
        if s["cash"] - cost < 0:
            _err("INSUFFICIENT_FUNDS")
        s["cash"] -= cost
        moved = _take_fifo(s["lots"][sku][from_wh], qty)
        s["lots"][sku][to_wh] = sorted(s["lots"][sku][to_wh] + moved, key=lambda p: p[0])

    def return_goods(self, sku, qty, wh, price):
        return self._txn(self._return_goods, sku, qty, wh, price)

    def _return_goods(self, sku, qty, wh, price):
        s = self._s
        self._need_sku(sku)
        self._need_wh(wh)
        self._need_qty(qty)
        self._need_nonneg(price)
        if s["returned"].get(sku, 0) + qty > s["shipped"].get(sku, 0):
            _err("RETURN_EXCEEDS")
        if self._wh_units(wh) + qty > self._cap[wh]:
            _err("CAPACITY")
        refund = price * qty
        if s["cash"] - refund < 0:
            _err("INSUFFICIENT_FUNDS")
        s["cash"] -= refund
        s["lots"][sku][wh].append([s["day"], qty])   # C23: literal reading, perishables too
        s["returned"][sku] = s["returned"].get(sku, 0) + qty

    def audit(self, counts):
        return self._txn(self._audit, counts)

    def _audit(self, counts):
        s = self._s
        if not isinstance(counts, dict):
            _err("BAD_ARG")
        if not counts:
            _err("EMPTY_AUDIT")
        for key, counted in counts.items():
            if not isinstance(key, tuple) or len(key) != 2:
                _err("BAD_ARG")
            self._need_sku(key[0])
            self._need_wh(key[1])
            self._need_nonneg(counted)
        for key in sorted(counts):
            sku, wh = key
            ledger = self._stock(sku, wh)
            if ledger != counts[key]:
                s["notes"].append(("AUDIT_MISMATCH", sku, wh, ledger, counts[key]))

    def advance_day(self):
        self._txn(self._advance, undoable=False)

    def _advance(self):
        s = self._s
        # C21 order: storage charge, then expiry, then the overdrawn check.
        s["cash"] -= self._total_units() * STORAGE_PER_UNIT_DAY
        for sku in sorted(s["items"]):
            life = s["items"][sku]["life"]
            if life is None:
                continue
            for wh in sorted(self._wh):
                kept, expired, any_expired = [], 0, False
                for day, q in s["lots"][sku][wh]:
                    if s["day"] - day > life:
                        expired += q
                        any_expired = True
                    else:
                        kept.append([day, q])
                if any_expired:
                    s["lots"][sku][wh] = kept
                    s["notes"].append(("EXPIRY", sku, wh, expired))
        if s["cash"] < 0:
            s["notes"].append(("OVERDRAWN",))
        s["day"] += 1
        s["held"].append(self._total_units())

    def place_order(self, supplier, sku, qty, due_day, wh=None):
        return self._txn(self._place_order, supplier, sku, qty, due_day, wh)

    def _place_order(self, supplier, sku, qty, due_day, wh):
        s = self._s
        self._need_sku(sku)
        self._need_qty(qty)
        if not _is_int(due_day):
            _err("BAD_ARG")
        if wh is not None:
            self._need_wh(wh)                  # C16: optional destination (assumption)
        if not isinstance(supplier, str) or not supplier:
            _err("BAD_ARG")
        rel = s["suppliers"].get(supplier)
        if rel is not None and rel <= SUSPEND_AT:
            _err("SUPPLIER_SUSPENDED")
        if rel is None:
            s["suppliers"][supplier] = START_RELIABILITY
        oid = s["next_order"]
        s["next_order"] = oid + 1
        s["orders"][str(oid)] = {
            "supplier": supplier, "sku": sku, "qty": qty,
            "due": due_day, "wh": wh, "open": True,
        }
        return oid

    def deliver(self, order_id, day):
        return self._txn(self._deliver, order_id, day)

    def _deliver(self, order_id, day):
        s = self._s
        order = s["orders"].get(str(order_id)) if _is_int(order_id) else None
        if order is None:
            _err("UNKNOWN_ORDER")
        if not order["open"]:
            _err("ORDER_CLOSED")
        if not _is_int(day) or day != s["day"]:
            _err("BAD_ARG")
        wh = order["wh"]
        if wh is None:
            _err("UNKNOWN_WAREHOUSE")
        sku, qty = order["sku"], order["qty"]
        unit = s["items"][sku]["unit"]
        late = day > order["due"]
        if late:
            if self._late is None:
                _err("PENALTY_UNSET")              # C18: percentage not decided
            amount = _to_cents(Decimal(unit * qty) * (100 - self._late) / 100, self._mode)
        else:
            amount = unit * qty
        if s["cash"] < 0:
            _err("OVERDRAWN")
        if self._wh_units(wh) + qty > self._cap[wh]:
            _err("CAPACITY")
        if s["cash"] - amount < 0:
            _err("INSUFFICIENT_FUNDS")
        s["cash"] -= amount
        s["lots"][sku][wh].append([s["day"], qty])
        order["open"] = False

        sup = order["supplier"]
        old = s["suppliers"][sup]
        new = max(0, min(5, old - 1 if late else old + 1))
        s["suppliers"][sup] = new
        if old > SUSPEND_AT >= new:
            s["notes"].append(("SUPPLIER_SUSPENDED", sup))

    def reinstate(self, supplier):
        return self._txn(self._reinstate, supplier)

    def _reinstate(self, supplier):
        if not isinstance(supplier, str) or supplier not in self._s["suppliers"]:
            _err("UNKNOWN_SUPPLIER")
        self._s["suppliers"][supplier] = REINSTATE_TO

    def load(self, text):
        self._txn(self._load, text)

    def _load(self, text):
        try:
            obj = json.loads(text)
        except (TypeError, ValueError):
            _err("BAD_SAVE")
        if not isinstance(obj, dict) or type(obj.get("version")) is not int \
                or obj["version"] != SAVE_VERSION:
            _err("BAD_SAVE")
        st = obj.get("state")
        try:
            new = _validate_save(st, self._wh)
        except DepotError:
            raise
        except Exception:
            _err("BAD_SAVE")
        self._s = new

    def undo(self):
        if self._prev is None:
            _err("UNDO_BLOCKED")
        self._s = self._prev
        self._prev = None

    # ----- read-only ---------------------------------------------------------

    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    def reliability(self, supplier):
        if not isinstance(supplier, str) or supplier not in self._s["suppliers"]:
            _err("UNKNOWN_SUPPLIER")
        return self._s["suppliers"][supplier]

    def notifications(self):
        return list(self._s["notes"])

    def list_price(self, sku):
        self._need_sku(sku)
        return _to_cents(Decimal(self._s["items"][sku]["unit"]) * (1 + MARKUP), self._mode)

    def stock(self, sku, wh=None):
        self._need_sku(sku)
        if wh is None:
            return sum(self._stock(sku, w) for w in self._wh)
        self._need_wh(wh)
        return self._stock(sku, wh)

    def report(self):
        rows = []
        for sku in sorted(self._s["items"]):
            unit = self._s["items"][sku]["unit"]
            for wh in sorted(self._wh):
                units = self._stock(sku, wh)
                if units > 0:
                    rows.append((sku, wh, units, units * unit))
        return rows

    def turnover(self, start_day, end_day):
        s = self._s
        if not _is_int(start_day) or not _is_int(end_day) \
                or start_day < 0 or end_day > s["day"] or start_day > end_day:
            _err("BAD_ARG")
        shipped = sum(q for d, q in s["ship_log"] if start_day <= d <= end_day)
        avg = Fraction(sum(s["held"][start_day:end_day + 1]), end_day - start_day + 1)
        if avg == 0:
            return None
        return float(Fraction(shipped) / avg)

    def save(self):
        st = copy.deepcopy(self._s)
        st["notes"] = [list(n) for n in st["notes"]]
        return json.dumps({"version": SAVE_VERSION, "state": st}, sort_keys=True)


def simulate(days, seed):
    """One list of (sku, qty) orders per day. Same draw scheme as sim.py: sorted skus, one
    randint per sku per day, zero draws omitted. Only random.Random(seed) is used."""
    if not _is_int(days) or days < 0:
        _err("BAD_ARG")
    rng = random.Random(seed)
    out = []
    for _ in range(days):
        orders = []
        for sku in sorted(DEMAND):
            lo, hi = DEMAND[sku]
            qty = rng.randint(lo, hi)
            if qty > 0:
                orders.append((sku, qty))
        out.append(orders)
    return out
